document.addEventListener("alpine:init",()=>{Alpine.data("rccart",()=>({items:[],init(){RockCommerce.addComponent(this);RockCommerce.cart=this;this.$watch("items",this.update.bind(this));this.update()},addItem(pid,amount,variation){const item=new CartItem(pid,variation);while(amount>0){this.items.push(item);amount--}},get count(){return this.items.length},update(){this.updateCartCount()},updateCartCount(){let elements=document.querySelectorAll("[rc-cart-count]");elements.forEach((el)=>{el.textContent=this.count;if(this.count>0)el.removeAttribute("hidden");else el.setAttribute("hidden",!0)})},}));class CartItem{constructor(pid,variation){this.pid=parseInt(pid);this.variation=variation}}})